 let sport=sp.value,names={Tennis:tennisCategories,Swimming:['Kids','Juniors','Adults'],'Water Polo':['Kids','Teens','Veterans'],Padel:['Kids','Teens','Veterans'],Taekwondo:['Kids','Teens'],Fitness:['Kids','Juniors']}[sport]||[];
