 let existing=(st.occurrences||[]).filter(function(o){return o.player_id===player?.id&&o.registration_id===reg?.id}).map(function(o){return o.session_id+'|'+o.session_date}),checked=new Set(existing);
 let html='<div class=card><h2>Assign Player Schedule</h2><div class=small>Select a player. The player sport and category will filter the available slots.</div><div class=grid><label>Player<select id=slotPlayer onchange="st.slotPlayerId=this.value;st.selectedRegistration=null;st.slotFrom=null;st.slotTo=null;render()"><option value="">Select player...</option>'+st.players.map(function(p){return '<option value="'+p.id+'" '+(p.id===playerId?'selected':'')+'>'+p.name+' · '+[...new Set((p.registrations||[]).map(function(r){return r.sport||p.sport}).filter(Boolean))].join(' / ')+'</option>'}).join('')+'</select></label>';
