function sameSessionPattern(a,b){if(!a||!b)return false;let ac=(a.categories||a.tennis_categories||[]).slice().sort().join('|'),bc=(b.categories||b.tennis_categories||[]).slice().sort().join('|');let aa=(a.coach_ids||[]).slice().sort().join('|'),ba=(b.coach_ids||[]).slice().sort().join('|');return a.sport===b.sport&&Number(a.day_of_week)===Number(b.day_of_week)&&String(a.start_time).slice(0,5)===String(b.start_time).slice(0,5)&&(a.location||'')===(b.location||'')&&ac===bc&&aa===ba}function updateAssignmentCount(){let box=document.getElementById('assignCount'),n=document.querySelectorAll('.assignOccurrence:checked').length;if(box)box.textContent='Selected '+n+' session'+(n===1?'':'s');}function toggleRecurringSlot(el){let sid=el.dataset.session,date=el.dataset.date,base=st.sessions.find(function(s){return s.id===sid});let checks=[...document.querySelectorAll('.assignOccurrence')];checks.forEach(function(x){let a=x.value.split('|'),s=st.sessions.find(function(q){return q.id===a[0]}),d=a[1];if(s&&sameSessionPattern(base,s)&&d>=date)x.checked=el.checked});updateAssignmentCount()}async function savePlayerSchedule(id){let ids=[...document.querySelectorAll('.assignOccurrence:checked')].map(function(x){let a=x.value.split('|');return {session_id:a[0],session_date:a[1]}});if(!ids.length&&!confirm('No slots are selected. This will remove all assigned slots from this registration and update the schedule. Continue?'))return;try{let result=await j('/registration-schedule-save',{method:'POST',body:JSON.stringify({registration_id:id,occurrences:ids})});st.selectedRegistration=id;await load()}catch(e){alert(e.message||'Could not update the player schedule. Please check the selected sessions.')}}function registrationSlots(c){let regs=[];st.players.forEach(function(p){(p.registrations||[]).forEach(function(r){regs.push({...r,player:p})})});let chosen=regs.find(function(r){return r.id===st.selectedRegistration})||regs[0];if(!chosen){c.innerHTML='<div class=card><h2>Registration Slots</h2><span class=small>No registrations available.</span></div>';return}st.selectedRegistration=chosen.id;let start=new Date(chosen.start_date+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+Math.max(1,+chosen.number_weeks||1)*7-1);let slots=st.sessions.filter(function(s){return s.sport===chosen.player.sport}).filter(function(s){return (!s.start_date||s.start_date<=localISO(end))&&(!s.end_date||s.end_date>=localISO(start))});if(chosen.player.sport==='Tennis')slots=slots.filter(function(s){return (s.categories||s.tennis_categories||[]).some(function(x){return (chosen.player.tennis_categories||[]).includes(x)})});slots.sort(function(a,b){return a.day_of_week-b.day_of_week||a.start_time.localeCompare(b.start_time)});let selected=chosen.session_ids||[];c.innerHTML='<div class=card><div class=row><div><h2>Registration Slots</h2><div class=small>'+chosen.player.name+' -'+chosen.registration_no+' · '+(chosen.package_name||'')+' · '+chosen.sessions_per_week+' slot'+(chosen.sessions_per_week==1?'':'s')+' per week · '+chosen.start_date+' to '+localISO(end)+'</div></div><select onchange="st.selectedRegistration=this.value;render()">'+regs.map(function(r){return '<option value="'+r.id+'" '+(r.id===chosen.id?'selected':'')+'>'+r.player.name+' -'+r.registration_no+' · '+(r.package_name||'')+'</option>'}).join('')+'</select></div><p class=small>Select the recurring slots applicable to this player group. Options show day, time, coach, location and active dates.</p><div class=registration-sessions>'+slots.map(function(s){return '<label class=check><input class=assignSlot type=checkbox value="'+s.id+'" '+(selected.includes(s.id)?'checked':'')+'> <b>'+days[s.day_of_week]+' · '+s.start_time.slice(0,5)+'</b> · '+(s.coach_name||'Coach TBD')+' · '+(s.location||'Location TBD')+(s.sport==='Tennis'?' · '+(s.categories||s.tennis_categories||[]).join(', '):'')+'<br><span class=small>'+(s.start_date||'-')+' to '+(s.end_date||'ongoing')+'</span></label>'}).join('')||'<span class=small>No applicable slots found.</span>'+'</div><button class=p onclick="assignRegistrationSlots(\''+chosen.id+'\')">Update registration schedule</button></div>'}async function assignRegistrationSlots(id){let ids=[...document.querySelectorAll('.assignSlot:checked')].map(function(x){return x.value}),r=st.players.flatMap(function(p){return p.registrations||[]}).find(function(x){return x.id===id});if(!r)return;if(ids.length!==+r.sessions_per_week)return alert('Select exactly '+r.sessions_per_week+' slot'+(r.sessions_per_week==1?'':'s')+'.');await j('/registration-assign',{method:'POST',body:JSON.stringify({registration_id:id,session_ids:ids})});st.selectedRegistration=id;await load()}function packages(c){let e=st.packages.find(x=>x.id===st.selected);c.innerHTML=`<div class=card><h2>${e?'Edit package':'Create package'}</h2><div class=grid><input id=pakname placeholder='Package name' value="${e?.name||''}"><select id=paksport>${sports.map(x=>`<option ${e?.sport===x?'selected':''}>${x}</option>`).join('')}</select><select id=paktype onchange="refreshPackageType()"><option ${(e?.package_type||'Monthly')==='Monthly'?'selected':''}>Monthly</option><option ${e?.package_type==='Term'?'selected':''}>Term</option><option ${e?.package_type==='Private'?'selected':''}>Private</option><option ${e?.package_type==='Trial'?'selected':''}>Trial</option></select><select id=paksessions><option value=1 ${+e?.sessions_per_week===1?'selected':''}>1</option><option value=2 ${+e?.sessions_per_week===2?'selected':''}>2</option><option value=3 ${+e?.sessions_per_week===3?'selected':''}>3</option><option value=4 ${+e?.sessions_per_week===4?'selected':''}>4</option></select><div id=packageDates></div><input id=pakprice type=number step=.01 placeholder='Reference price (BD)' value="${e?.price??''}"><input id=paknetprice type=number step=.01 placeholder='Net price (BD)' value="${e?.net_price??''}"></div><button class=p onclick="${e?`updatePackage('${e.id}')`:'addPackage()'}">${e?'Save changes':'Create package'}</button>${e?` <button class=s onclick="st.selected=null;render()">Cancel</button>`:''}</div><div class=card><h2>Packages</h2>${st.packages.map(x=>`<div class=session><div class=row><div><b>${x.name}</b> <span class=pill>${x.sport}</span> <span class=pill>${x.package_type||'Monthly'}</span></div><div><button class=s onclick="st.selected='${x.id}';render()">Edit</button> <button class=s onclick="deletePackage('${x.id}')">Delete</button></div></div><div class=small>${x.sessions_per_week||'-'} sessions/week · ${x.duration_weeks||'-'} weeks · Reference: ${x.price??'-'} BD · Net: ${x.net_price??'-'} BD${x.package_type==='Term'&&x.start_date?' · '+x.start_date+' to '+x.end_date:''}</div><div class=small>${st.players.filter(p=>(p.packages||[]).some(q=>q.id===x.id)).length} registered players</div></div>`).join('')||'<span class=small>No packages yet.</span>'}</div>`;refreshPackageType()}
function refreshPackageType(){let type=document.getElementById('paktype'),box=document.getElementById('packageDates');if(!type||!box)return;let e=st.packages.find(x=>x.id===st.selected),t=type.value;if(t==='Monthly')box.innerHTML='<label>Number of weeks<input id=pakweeks type=number value=4 readonly></label>';else if(t==='Term')box.innerHTML=`<label>Start date<input id=pakstart type=date value="${e?.start_date?.slice(0,10)||localISO(new Date())}" onchange="calcPackageWeeks()"></label><label>End date<input id=pakend type=date value="${e?.end_date?.slice(0,10)||''}" onchange="calcPackageWeeks()"></label><label>Number of weeks<input id=pakweeks type=number value="${e?.duration_weeks||''}" readonly></label>`;else box.innerHTML=`<label>Number of weeks<input id=pakweeks type=number min=1 value="${e?.duration_weeks||4}"></label>`;calcPackageWeeks()}
function calcPackageWeeks(){let type=document.getElementById('paktype')?.value,w=document.getElementById('pakweeks');if(!w)return;if(type==='Monthly'){w.value=4;return}if(type==='Trial'){w.value=1;return}if(type==='Term'){let a=document.getElementById('pakstart')?.value,b=document.getElementById('pakend')?.value;if(a&&b&&b>=a)w.value=Math.max(1,Math.ceil((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/604800000));else w.value=''}}async function addPackage(){if(!pakname.value.trim())return;let t=paktype.value;if(t==='Term'&&(!pakstart.value||!pakend.value||pakend.value<pakstart.value))return alert('Enter valid term start and end dates.');await j('/package-add',{method:'POST',body:JSON.stringify({name:pakname.value.trim(),sport:paksport.value,sessions_per_week:+paksessions.value,duration_weeks:+pakweeks.value,price:pakprice.value,net_price:paknetprice.value,package_type:t,start_date:t==='Term'?pakstart.value:null,end_date:t==='Term'?pakend.value:null})});st.selected=null;load()}async function updatePackage(id){if(!pakname.value.trim())return;let t=paktype.value;if(t==='Term'&&(!pakstart.value||!pakend.value||pakend.value<pakstart.value))return alert('Enter valid term start and end dates.');await j('/package-update',{method:'POST',body:JSON.stringify({id,name:pakname.value.trim(),sport:paksport.value,sessions_per_week:+paksessions.value,duration_weeks:+pakweeks.value,price:pakprice.value,net_price:paknetprice.value,package_type:t,start_date:t==='Term'?pakstart.value:null,end_date:t==='Term'?pakend.value:null})});st.selected=null;load()}async function deletePackage(id){if(!confirm('Delete this package? Players will no longer be linked to it.'))return;await j('/package-delete',{method:'POST',body:JSON.stringify({id})});st.selected=null;load()}function coaches(c){c.innerHTML=`<div class=card><h2>Add coach</h2><div class=grid><input id=cn placeholder='Coach name'><div class=card><b>Sports</b><div class=registration-sessions>${sports.map(x=>`<label class=check><input class=coachSport type=checkbox value=\"${x}\">${x}</label>`).join('')}</div></div></div><button class=p onclick=addCoach()>Add coach</button></div><div class=card>${st.coaches.map(x=>`<div class=session><b>${x.name}</b> <span class=pill>${(x.sports||[x.sport]).join(' / ')}</span></div>`).join('')}</div>`}async function addCoach(){if(!cn.value.trim())return;let selected=[...document.querySelectorAll('.coachSport:checked')].map(x=>x.value);if(!selected.length)return alert('Select at least one sport.');await j('/coach-add',{method:'POST',body:JSON.stringify({name:cn.value.trim(),sports:selected})});load()}function coaches(c){let e=st.coaches.find(x=>x.id===st.selected);c.innerHTML=`<div class=card><h2>${e?'Edit coach':'Add coach'}</h2><div class=grid><input id=cn placeholder='Coach name' value="${e?.name||''}"><div class=card><b>Sports</b><div class=registration-sessions>${sports.map(x=>`<label class=check><input class=coachSport type=checkbox value="${x}" ${(e?.sports||[e?.sport]).includes(x)?'checked':''}>${x}</label>`).join('')}</div></div></div><button class=p onclick="${e?`updateCoach('${e.id}')`:'addCoach()'}">${e?'Save changes':'Add coach'}</button>${e?` <button class=s onclick="st.selected=null;render()">Cancel</button>`:''}</div><div class=card>${st.coaches.map(x=>`<div class=session><div class=row><div><b>${x.name}</b> <span class=pill>${(x.sports||[x.sport]).join(' / ')}</span></div><div><button class=s onclick="st.selected='${x.id}';render()">Edit</button> <button class=s onclick="deleteCoach('${x.id}')">Delete</button></div></div></div>`).join('')}</div>`}async function addCoach(){if(!cn.value.trim())return;let selected=[...document.querySelectorAll('.coachSport:checked')].map(x=>x.value);if(!selected.length)return alert('Select at least one sport.');await j('/coach-add',{method:'POST',body:JSON.stringify({name:cn.value.trim(),sports:selected})});st.selected=null;load()}async function updateCoach(id){if(!cn.value.trim())return;let selected=[...document.querySelectorAll('.coachSport:checked')].map(x=>x.value);if(!selected.length)return alert('Select at least one sport.');await j('/coach-update',{method:'POST',body:JSON.stringify({id,name:cn.value.trim(),sports:selected})});st.selected=null;load()}async function deleteCoach(id){let x=st.coaches.find(q=>q.id===id);if(!x)return;if(!confirm('Delete '+x.name+'? Historical sessions will remain intact.'))return;await j('/coach-delete',{method:'POST',body:JSON.stringify({id})});st.selected=null;load()}function attendance(c){let ws=weekStart();let html='<div class=card><div class=row><h2>Attendance</h2><button class=s onclick="st.weekOffset--;render()">← Previous</button><button class=p onclick="st.weekOffset=0;render()">Current week</button><button class=s onclick="st.weekOffset++;render()">Next →</button></div><div class=row><b>'+weekLabel()+'</b></div>';days.forEach((d,i)=>{let dt=new Date(ws);dt.setDate(ws.getDate()+i);let ss=st.sessions.filter(s=>+s.day_of_week===i&&activeOnDate(s,dt)).sort((a,b)=>a.start_time.localeCompare(b.start_time));html+='<div class=card><h3>'+d+' <span class=small>'+dateLabel(dt)+'</span></h3>';if(!ss.length)html+='<span class=small>No sessions</span>';ss.forEach(s=>{html+='<div class=session><b>'+s.start_time.slice(0,5)+' · '+s.sport+'</b><div class=small>'+(s.coach_name||'Coach TBD')+'</div>';let dayReg=(st.occurrences||[]).filter(o=>o.session_id===s.id&&o.session_date===localISO(dt));dayReg.forEach(p=>{html+='<label class=check><input type=checkbox '+(p.status==='Present'?'checked':'')+' onchange="attDate(\''+s.id+'\',\''+p.player_id+'\',\''+p.session_date+'\',this.checked)">'+p.player_name+' · '+p.status+'</label>'});let dayPlayers=dayReg.map(o=>({id:o.player_id,name:o.player_name,status:o.status}));let gs=(st.guests||[]).filter(g=>g.academy_session_id===s.id&&g.session_date===localISO(dt));gs.forEach(g=>{html+='<label class=check><input type=checkbox '+(g.status==='Present'?'checked':'')+' onchange="attGuest(\''+g.id+'\',this.checked)">'+g.guest_name+' · Other · '+g.status+'</label>'});html+='<div class=grid><select id="attadd_'+s.id+'"><option value="">Add unplanned player...</option>'+st.players.filter(p=>p.sport===s.sport&&!dayPlayers.some(x=>x.id===p.id)).map(p=>'<option value='+p.id+'>'+p.name+' · '+p.level+'</option>').join('')+'<option value="__other__">Other</option></select><button class=p onclick="addUnplanned(\''+s.id+'\',\''+localISO(dt)+'\')">Add</button></div><div id="otherbox_'+s.id+'" style="display:none" class=grid><input id="other_'+s.id+'" placeholder="Other player name"><button class=s onclick="addOther(\''+s.id+'\',\''+localISO(dt)+'\')">Add other</button></div></div>'});html+='</div>'});c.innerHTML=html;document.querySelectorAll('[id^=attadd_]').forEach(el=>el.onchange=()=>{let id=el.id.slice(7),b=document.getElementById('otherbox_'+id);if(b)b.style.display=el.value==='__other__'?'grid':'none'})}async function addUnplanned(id,date){let el=document.getElementById('attadd_'+id);if(!el||!el.value||el.value==='__other__')return;await j('/attendance-add-player',{method:'POST',body:JSON.stringify({session_id:id,player_id:el.value,status:'Present',session_date:date})});load()}async function addOther(id,date){let el=document.getElementById('other_'+id);if(!el||!el.value.trim())return;await j('/attendance-add-player',{method:'POST',body:JSON.stringify({session_id:id,guest_name:el.value.trim(),status:'Present',session_date:date})});load()}async function attDate(s,p,d,v){let status=v===true?'Present':v===false?'Absent':v;await j('/attendance-set',{method:'POST',body:JSON.stringify({session_id:s,player_id:p,session_date:d,status})});load()}async function attGuest(id,v){await j('/attendance-set',{method:'POST',body:JSON.stringify({guest_id:id,status:v?'Present':'Absent'})});load()}async function accessManagement(c){
 const rows=await j('/user-access')||[];
 c.innerHTML=`<div class="pagehead"><div><h1>User / Access Management</h1><div class="small">Grant or remove MSA Academy app access by email.</div></div></div>
 <div class="card"><h2>Grant access</h2><div class="grid"><input id="accessEmail" type="email" placeholder="Email address"><select id="accessType"><option value="manager">Manager</option><option value="coach">Coach</option></select><button class="p" onclick="grantAccess()">Grant access</button></div><p class="small">Owner has full access. Manager has all operational access except Academy Analytics and Financial Dashboard. Coach can view Schedule and update Attendance.</p></div>
 <div class="card"><h2>Active users</h2>${rows.map(x=>`<div class="session"><div class="row"><div><b>${x.email}</b><div class="small">${x.access_type==='manager'?'Manager':'Coach'}</div></div><button class="s" onclick="removeAccess('${x.id}')">Remove access</button></div></div>`).join('')||'<span class="small">No manager or coach access has been granted yet.</span>'}</div>
 <div class="card"><h2>Access model</h2><div class="small">Owner → full access + User / Access Management. Manager → operational management, Schedule, Players, Packages, Coaches and Attendance. Coach → Schedule and Attendance only.</div></div>`;
}
async function grantAccess(){let email=document.getElementById('accessEmail')?.value.trim(),access_type=document.getElementById('accessType')?.value;if(!email)return alert('Enter an email address.');await j('/user-access',{method:'POST',body:JSON.stringify({email,access_type})});render()}
async function removeAccess(id){if(!confirm('Remove this user access?'))return;await j('/user-access',{method:'DELETE',body:JSON.stringify({id})});render()}
